import { createRouter } from "@tanstack/react-router";
import { queryClient } from "./query";
import { routeTree } from "./routeTree.gen";

// `routeTree.gen.ts` is generated by @tanstack/router-plugin (Vite) on
// `pnpm dev` and `pnpm build`. It is gitignored; do not edit by hand.

export const router = createRouter({
  routeTree,
  // Preload on link hover/focus.
  defaultPreload: "intent",
  // Let TanStack Query own caching/staleness; router does not re-cache.
  defaultPreloadStaleTime: 0,
  // Root context type is declared in src/routes/__root.tsx via
  // createRootRouteWithContext<{ queryClient: QueryClient }>().
  context: { queryClient },
  scrollRestoration: true,
});

// Register the router instance for global type-safety (Link, useNavigate, ...).
declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}
